export function validTakePreset(data){return !!data&&data.version===1&&Object.keys(data).every(k=>['version','name','fps','tolerance','settings','description','sources','parentPreset','overrides','clock'].includes(k))&&typeof data.name==='string'&&!!data.name&&data.name.length<=80&&!data.name.includes('\0')&&Number.isInteger(data.fps)&&data.fps>=1&&data.fps<=240&&validTakeTolerance(data.tolerance)&&validTakeSettings(data.settings)&&validTakeInheritance(data)&&(data.clock===undefined||validTakeClock(data.clock))&&(data.sources===undefined||validTakeSources(data.sources))&&(data.description===undefined||typeof data.description==='string'&&data.description.length<=1000&&!data.description.includes('\0'));}
